"""Half-open integer interval operations."""


def _clean(intervals):
    return sorted((s, e) for s, e in intervals if s < e)


def merge(intervals):
    result = []
    for start, end in _clean(intervals):
        if result and start <= result[-1][1]:
            if end > result[-1][1]:
                result[-1] = (result[-1][0], end)
        else:
            result.append((start, end))
    return result


def free_gaps(intervals, window):
    ws, we = window
    if ws >= we:
        return []
    merged = merge((max(s, ws), min(e, we)) for s, e in _clean(intervals) if s < we and e > ws)
    gaps = []
    cur = ws
    for start, end in merged:
        if start > cur:
            gaps.append((cur, start))
        cur = max(cur, end)
    if cur < we:
        gaps.append((cur, we))
    return gaps


def max_overlap(intervals):
    events = []
    for s, e in _clean(intervals):
        events.append((s, 1))
        events.append((e, -1))
    # at equal coordinates, half-open means closes happen before opens count
    events.sort(key=lambda p: (p[0], p[1]))
    depth = best = 0
    for _, delta in events:
        depth += delta
        if depth > best:
            best = depth
    return best

"""LRU cache with per-entry time-to-live."""

from collections import OrderedDict


class TTLCache:
    def __init__(self, capacity, clock=None):
        if not isinstance(capacity, int) or capacity < 1:
            raise ValueError("capacity must be >= 1")
        if clock is None:
            import time
            clock = time.monotonic
        self._capacity = capacity
        self._clock = clock
        self._entries = OrderedDict()  # key -> (value, expiry); expiry is None if no ttl

    def _is_expired(self, expiry):
        return expiry is not None and self._clock() >= expiry

    def _purge_expired(self):
        now = self._clock()
        expired = [k for k, (_, expiry) in self._entries.items()
                   if expiry is not None and now >= expiry]
        for k in expired:
            del self._entries[k]
        return len(expired)

    def put(self, key, value, ttl=None):
        if ttl is not None and ttl <= 0:
            raise ValueError("ttl must be > 0")
        if key in self._entries:
            del self._entries[key]
        elif len(self._entries) >= self._capacity:
            removed = self._purge_expired()
            if len(self._entries) >= self._capacity:
                self._entries.popitem(last=False)
        expiry = None if ttl is None else self._clock() + ttl
        self._entries[key] = (value, expiry)

    def get(self, key, default=None):
        if key not in self._entries:
            return default
        value, expiry = self._entries[key]
        if self._is_expired(expiry):
            del self._entries[key]
            return default
        self._entries.move_to_end(key)
        return value

    def __contains__(self, key):
        if key not in self._entries:
            return False
        return not self._is_expired(self._entries[key][1])

    def __len__(self):
        self._purge_expired()
        return len(self._entries)

    def keys(self):
        self._purge_expired()
        return list(self._entries.keys())

    def evict_expired(self):
        return self._purge_expired()

"""Arithmetic expression evaluator (tokenizer + recursive-descent parser)."""

import operator as _op


class _Parser:
    def __init__(self, tokens):
        self.tokens = tokens
        self.pos = 0

    def peek(self):
        if self.pos < len(self.tokens):
            return self.tokens[self.pos]
        return (None, None)

    def advance(self):
        tok = self.peek()
        self.pos += 1
        return tok

    def expect(self, kind, value=None):
        k, v = self.advance()
        if k != kind or (value is not None and v != value):
            raise ValueError("expected %s, got %s" % (value or kind, v))
        return k, v

    def at_end(self):
        return self.pos >= len(self.tokens)

    # expression := addsub
    def parse(self):
        val = self.addsub()
        if not self.at_end():
            raise ValueError("unexpected token: %s" % (self.peek()[1],))
        return val

    def addsub(self):
        left = self.muldiv()
        while True:
            k, v = self.peek()
            if v in ("+", "-") and k == "op":
                self.advance()
                right = self.muldiv()
                left = left + right if v == "+" else left - right
            else:
                return left

    def muldiv(self):
        left = self.unary()
        while True:
            k, v = self.peek()
            if k == "op" and v in ("*", "/", "//", "%"):
                self.advance()
                right = self.unary()
                if v == "*":
                    left = left * right
                elif v == "/":
                    left = left / right
                elif v == "//":
                    left = left // right
                else:
                    left = left % right
            else:
                return left

    def unary(self):
        k, v = self.peek()
        if k == "op" and v in ("+", "-"):
            self.advance()
            operand = self.unary()
            return -operand if v == "-" else +operand
        return self.power()

    def power(self):
        base = self.primary()
        k, v = self.peek()
        if k == "op" and v == "**":
            self.advance()
            exponent = self.unary()
            return base ** exponent
        return base

    def primary(self):
        k, v = self.peek()
        if k == "num":
            self.advance()
            return v
        if k == "lparen":
            self.advance()
            val = self.addsub()
            self.expect("rparen", ")")
            return val
        if k == "name":
            self.advance()
            if v not in ("min", "max", "abs"):
                raise ValueError("unknown function: %s" % v)
            self.expect("lparen", "(")
            args = []
            if self.peek() == ("rparen", ")"):
                raise ValueError("wrong number of arguments for %s" % v)
            args.append(self.addsub())
            while self.peek() == ("op", ","):
                self.advance()
                args.append(self.addsub())
            self.expect("rparen", ")")
            if v == "abs":
                if len(args) != 1:
                    raise ValueError("wrong number of arguments for abs")
                return abs(args[0])
            if v == "min":
                return min(args)
            return max(args)
        raise ValueError("unexpected token: %s" % (v,))


def _tokenize(text):
    tokens = []
    i = 0
    n = len(text)
    while i < n:
        c = text[i]
        if c.isspace():
            i += 1
            continue
        if c.isdigit() or (c == "." and i + 1 < n and text[i + 1].isdigit()):
            j = i
            seen_dot = False
            while j < n and (text[j].isdigit() or (text[j] == "." and not seen_dot)):
                if text[j] == ".":
                    seen_dot = True
                j += 1
            lit = text[i:j]
            if seen_dot:
                tokens.append(("num", float(lit)))
            else:
                tokens.append(("num", int(lit)))
            i = j
            continue
        if c.isalpha():
            j = i
            while j < n and (text[j].isalnum() or text[j] == "_"):
                j += 1
            tokens.append(("name", text[i:j]))
            i = j
            continue
        if c == "*" and i + 1 < n and text[i + 1] == "*":
            tokens.append(("op", "**"))
            i += 2
            continue
        if c == "/" and i + 1 < n and text[i + 1] == "/":
            tokens.append(("op", "//"))
            i += 2
            continue
        if c in "+-*/%":
            tokens.append(("op", c))
            i += 1
            continue
        if c == "(":
            tokens.append(("lparen", c))
            i += 1
            continue
        if c == ")":
            tokens.append(("rparen", c))
            i += 1
            continue
        if c == ",":
            tokens.append(("op", ","))
            i += 1
            continue
        raise ValueError("unknown character: %s" % c)
    return tokens


def evaluate(text):
    if not isinstance(text, str):
        raise ValueError("input must be a string")
    tokens = _tokenize(text)
    if not tokens:
        raise ValueError("empty expression")
    return _Parser(tokens).parse()
